import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.CZqXuAiL.js";const c=JSON.parse('{"title":"Installation","description":"Install Blue Server Properties Editor — Blueprint, standalone manual, or the Blueprint-free PanelFiles path.","frontmatter":{"title":"Installation","description":"Install Blue Server Properties Editor — Blueprint, standalone manual, or the Blueprint-free PanelFiles path."},"headers":[],"relativePath":"blue-server-properties/getting-started/installation.md","filePath":"blue-server-properties/getting-started/installation.md","lastUpdated":1785522590000}'),n={name:"blue-server-properties/getting-started/installation.md"};function r(l,e,o,p,h,d){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Blue Server Properties Editor supports <strong>three</strong> install paths — more than any other PingLess panel addon:</p><table tabindex="0"><thead><tr><th>Path</th><th>When to use</th></tr></thead><tbody><tr><td><strong>Blueprint</strong> (recommended)</td><td>Blueprint CLI available on the panel</td></tr><tr><td><strong>Standalone (manual)</strong></td><td>Blueprint framework present, but the CLI fails or you want to audit changes</td></tr><tr><td><strong>Blueprint-free</strong> (<code>data/PanelFiles/</code>)</td><td>Panels with <strong>no Blueprint at all</strong></td></tr></tbody></table><p>Every release zip (<code>blue-server-properties-vX.Y.Z.zip</code>) contains <code>blueprint/</code> (the <code>.blueprint</code> + guide) and <code>standalone/</code> (all files + guide, including the PanelFiles tree).</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Pterodactyl Panel <strong>1.11.x – 1.14.x</strong> (tested on <strong>1.14.1</strong>)</li><li>For the Blueprint paths: Blueprint framework <code>beta-2026-01</code>, <code>beta-2026-02</code>, <code>beta-2026-05</code>, or <code>beta-2026-06</code></li><li>Root or sudo SSH access to the panel server</li><li>At least one <strong>Minecraft</strong> server (the editor only works on nest ID <code>1</code>)</li></ul><h2 id="blueprint-install-recommended" tabindex="-1">Blueprint install (recommended) <a class="header-anchor" href="#blueprint-install-recommended" aria-label="Permalink to &quot;Blueprint install (recommended)&quot;">​</a></h2><ol><li><p>Download <code>blueserverproperties-vX.Y.Z.blueprint</code> from the <a href="https://github.com/AnAverageBeing/blue-server-properties/releases" target="_blank" rel="noreferrer">latest release</a>.</p></li><li><p>Copy it into your panel directory and run the installer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueserverproperties-vX.Y.Z.blueprint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl/</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueserverproperties-vX.Y.Z</span></span></code></pre></div></li><li><p>Wait for Blueprint to finish — it rebuilds the panel frontend (<code>yarn build:production</code>).</p></li></ol><h2 id="standalone-manual-install" tabindex="-1">Standalone (manual) install <a class="header-anchor" href="#standalone-manual-install" aria-label="Permalink to &quot;Standalone (manual) install&quot;">​</a></h2><p>Follow <code>standalone/INSTALLATION.md</code> in the release zip: replace placeholders, place controllers/router/admin files, register the extension (<code>.store/conf.yml</code>, <code>installed_extensions</code>), copy + symlink components, add the <code>routes.ts</code> navigation entry and the optional <code>NavButtonUpdater</code> wrapper injections, then rebuild the frontend and clear caches.</p><div class="warning custom-block"><p class="custom-block-title">The Blueprint framework is still required for this path</p><p>&quot;Standalone&quot; replaces the <strong>CLI</strong>, not the framework — the admin controller uses <code>BlueprintAdminLibrary</code> and the components import through the <code>@/blueprint/extensions/*</code> alias. For a truly Blueprint-free panel, use the next section.</p></div><h2 id="blueprint-free-install-no-blueprint-at-all" tabindex="-1">Blueprint-free install (no Blueprint at all) <a class="header-anchor" href="#blueprint-free-install-no-blueprint-at-all" aria-label="Permalink to &quot;Blueprint-free install (no Blueprint at all)&quot;">​</a></h2><p>The extension ships a second, genuinely Blueprint-free variant inside <code>data/PanelFiles/</code> (a mirror of the panel tree — it only <strong>adds</strong> files). Full steps are in <code>standalone/INSTALLATION.md</code>; in short:</p><ol><li><p>Back up <code>routes/api-client.php</code> and <code>resources/scripts/routers/routes.ts</code>.</p></li><li><p><code>cp -a data/PanelFiles/. /var/www/pterodactyl/</code></p></li><li><p>Register the API routes in <code>routes/api-client.php</code> inside the <code>/servers/{server}</code> group:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;prefix&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/servercfg&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;middleware&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Pterodactyl\\Http\\Middleware\\Api\\Client\\Server\\MinecraftServerCheck</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]], </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Pterodactyl\\Http\\Controllers\\Api\\Client\\Servers\\ServerConfigEditorController</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fetch&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">post</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/update&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Pterodactyl\\Http\\Controllers\\Api\\Client\\Servers\\ServerConfigEditorController</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;update&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div></li><li><p>Register the frontend route in <code>resources/scripts/routers/routes.ts</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ServerConfigEditor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@/components/server/servercfg/ServerConfigEditor&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// in the \`server\` array:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;/servercfg&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Server Properties&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: ServerConfigEditor },</span></span></code></pre></div></li><li><p><code>yarn build:production</code> as the web user, clear caches, fix ownership.</p></li></ol><p><strong>Limitations of this path:</strong> no admin settings page and no custom navbar text (those are Blueprint-only). The tab appears on non-Minecraft servers too, but the middleware/backend reject them.</p><h2 id="post-install-verification" tabindex="-1">Post-install verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-install verification&quot;">​</a></h2><ul><li><strong>Admin area</strong> (Blueprint paths): <strong>Admin → Extensions → Blue Server Properties Editor</strong> — set the sidebar button text.</li><li><strong>Server area</strong>: open a Minecraft server — the <strong>Server Properties</strong> tab appears in the sidebar (<code>/server/&lt;id&gt;/servercfg</code>) and lists the live config.</li><li><strong>Smoke test</strong>: toggle any value, save, and confirm the change landed in the server&#39;s <code>server.properties</code> (Files → open the file).</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>Sidebar tab missing after install</td><td>Rebuild the frontend: <code>sudo -u www-data yarn install &amp;&amp; sudo -u www-data yarn build:production</code> (on Node ≥ 17 export <code>NODE_OPTIONS=--openssl-legacy-provider</code> first).</td></tr><tr><td>&quot;This feature is only available for Minecraft servers&quot;</td><td>Expected on non-Minecraft nests (the editor targets nest ID <code>1</code>).</td></tr><tr><td>&quot;Unable to retrieve server configuration file.&quot;</td><td>The server has no <code>server.properties</code> in its root, or Wings could not read it. Check the node/Wings logs.</td></tr><tr><td>Custom button text not applying</td><td>Hard-refresh the browser; the label is fetched from <code>/api/client/extensions/blueserverproperties/settings/nav-text</code> on each page.</td></tr></tbody></table><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p><strong>Blueprint:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blueserverproperties</span></span></code></pre></div><p><strong>Standalone / Blueprint-free:</strong> reverse the documented steps — remove the placed files and symlinks, revert the <code>routes.ts</code> / <code>api-client.php</code> edits (restore the <code>.bak-servercfg</code> backups on the Blueprint-free path), then rebuild the frontend and clear caches.</p>`,23)])])}const u=s(n,[["render",r]]);export{c as __pageData,u as default};
